核心 CSS 变量：

```css
:root {
  /* 上部/整体背景 —— 沿用原图浅灰绿留白，柔和舒适、不过深 */
  --color-bg-main: #F0F5EE;
  --color-bg-soft: #E9F0E6;
  --color-bg-surface: #FFFFFF;      /* 内容白卡 */

  /* 底部区域 —— 统一青绿色（#00C4A3 系） */
  --color-footer: #00C4A3;
  --color-footer-deep: #00A88D;     /* 文字密集区深化，保证白字对比度 */
  --color-footer-edge: #7FE0CE;     /* 过渡缓冲色 */

  /* 上部→底部渐变过渡，避免生硬跳色 */
  --gradient-bg-to-footer: linear-gradient(180deg, #F0F5EE 0%, #7FE0CE 62%, #00C4A3 100%);

  /* 文字颜色 —— 深墨绿主文字（对比度约 12:1），青绿底用白色加粗 */
  --color-text-primary: #21402F;
  --color-text-secondary: #4A5A52;
  --color-text-accent: #3E8E4E;
  --color-text-on-footer: #FFFFFF;

  --color-brand-deep: #1E4D3B;      /* 品牌墨绿重音（按钮/图标） */
  --color-divider: #ECECEC;
}
```

